var data = {lines:[
{"lineNum":"    1","line":"#!/usr/bin/env bash"},
{"lineNum":"    2","line":"#"},
{"lineNum":"    3","line":"# nopasswd-sudo.sh — toggle temporary passwordless sudo for a user."},
{"lineNum":"    4","line":"#"},
{"lineNum":"    5","line":"# Handy during migration/maintenance sessions that run many sudo commands"},
{"lineNum":"    6","line":"# non-interactively (e.g. driven over SSH). Turn it ON at the start, OFF when"},
{"lineNum":"    7","line":"# done. The drop-in is validated with `visudo` before being installed, so a"},
{"lineNum":"    8","line":"# typo can\'t lock you out of sudo."},
{"lineNum":"    9","line":"#"},
{"lineNum":"   10","line":"# Enabling also arms an auto-revoke so you can never leave passwordless sudo on"},
{"lineNum":"   11","line":"# by accident: an in-session timer switches it OFF after the timeout (default"},
{"lineNum":"   12","line":"# 30 min; pass a different number of minutes, or 0 to disable), AND a persistent"},
{"lineNum":"   13","line":"# boot-time unit clears it on every reboot. The in-session timer is transient"},
{"lineNum":"   14","line":"# and does NOT survive a reboot, so the boot unit is the reboot safety net —"},
{"lineNum":"   15","line":"# without it, a reboot would strand the grant with nothing left to revoke it."},
{"lineNum":"   16","line":"#"},
{"lineNum":"   17","line":"# Usage:"},
{"lineNum":"   18","line":"#   sudo ./nopasswd-sudo.sh on   [user] [minutes]   # default user: $SUDO_USER, default 30 min"},
{"lineNum":"   19","line":"#   sudo ./nopasswd-sudo.sh off"},
{"lineNum":"   20","line":"#   sudo ./nopasswd-sudo.sh status"},
{"lineNum":"   21","line":"#"},
{"lineNum":"   22","line":"set -o errexit","class":"lineCov","hits":"1","order":"2842",},
{"lineNum":"   23","line":"set -o nounset","class":"lineCov","hits":"1","order":"2845",},
{"lineNum":"   24","line":"set -o pipefail","class":"lineCov","hits":"1","order":"2840",},
{"lineNum":"   25","line":""},
{"lineNum":"   26","line":"# The two paths this writes to are taken from the environment when set. Both are system-wide and one of"},
{"lineNum":"   27","line":"# them governs sudo itself, so being able to point them elsewhere is what allows the grant, the revoke and"},
{"lineNum":"   28","line":"# the boot unit to be exercised without touching a real machine\'s sudoers; unset, they are the real ones."},
{"lineNum":"   29","line":": \"${DROPIN:=/etc/sudoers.d/99-temp-nopasswd}\"","class":"lineCov","hits":"1","order":"2883",},
{"lineNum":"   30","line":": \"${SYSTEMD_UNIT_DIR:=/etc/systemd/system}\"","class":"lineCov","hits":"1","order":"2852",},
{"lineNum":"   31","line":"readonly DROPIN SYSTEMD_UNIT_DIR","class":"lineCov","hits":"1","order":"2856",},
{"lineNum":"   32","line":"readonly AUTO_UNIT=\"nopasswd-sudo-autorevoke\"","class":"lineCov","hits":"1","order":"2861",},
{"lineNum":"   33","line":"readonly BOOT_UNIT=\"nopasswd-sudo-bootrevoke\"","class":"lineCov","hits":"1","order":"2864",},
{"lineNum":"   34","line":"readonly DEFAULT_TIMEOUT_MIN=30","class":"lineCov","hits":"1","order":"2833",},
{"lineNum":"   35","line":""},
{"lineNum":"   36","line":"#######################################"},
{"lineNum":"   37","line":"# Log an informational message to stdout."},
{"lineNum":"   38","line":"#######################################"},
{"lineNum":"   39","line":"log_info() { printf \'%s\\n\' \"$*\"; }"},
{"lineNum":"   40","line":""},
{"lineNum":"   41","line":"#######################################"},
{"lineNum":"   42","line":"# Log an error message to stderr."},
{"lineNum":"   43","line":"#######################################"},
{"lineNum":"   44","line":"log_error() { printf \'ERROR: %s\\n\' \"$*\" >&2; }"},
{"lineNum":"   45","line":""},
{"lineNum":"   46","line":"#######################################"},
{"lineNum":"   47","line":"# Print usage information."},
{"lineNum":"   48","line":"#######################################"},
{"lineNum":"   49","line":"show_usage() {"},
{"lineNum":"   50","line":"  cat <<EOF","class":"lineCov","hits":"1","order":"2847",},
{"lineNum":"   51","line":"Usage: sudo $(basename \"$0\") {on|off|status} [user] [minutes]"},
{"lineNum":"   52","line":""},
{"lineNum":"   53","line":"  on [user] [minutes]   grant passwordless sudo (default user: \\${SUDO_USER:-root})"},
{"lineNum":"   54","line":"                        and arm auto-revoke after [minutes] (default ${DEFAULT_TIMEOUT_MIN}; 0 = never)"},
{"lineNum":"   55","line":"  off                   revoke it now (removes ${DROPIN}, cancels the timer)"},
{"lineNum":"   56","line":"  status                show whether it is enabled and any armed auto-revoke"},
{"lineNum":"   57","line":""},
{"lineNum":"   58","line":"Examples:"},
{"lineNum":"   59","line":"  sudo $(basename \"$0\") on            # enable for \\$SUDO_USER, auto-off in ${DEFAULT_TIMEOUT_MIN} min"},
{"lineNum":"   60","line":"  sudo $(basename \"$0\") on 90         # enable for \\$SUDO_USER, auto-off in 90 min"},
{"lineNum":"   61","line":"  sudo $(basename \"$0\") on jure 0     # enable for jure, no auto-revoke"},
{"lineNum":"   62","line":"EOF"},
{"lineNum":"   63","line":"}"},
{"lineNum":"   64","line":""},
{"lineNum":"   65","line":"#######################################"},
{"lineNum":"   66","line":"# Abort unless running as root."},
{"lineNum":"   67","line":"#######################################"},
{"lineNum":"   68","line":"require_root() {"},
{"lineNum":"   69","line":"  if [[ \"${EUID}\" -ne 0 ]]; then","class":"lineCov","hits":"1","order":"2854",},
{"lineNum":"   70","line":"    log_error \"must run as root (use sudo).\"","class":"lineNoCov","hits":"0",},
{"lineNum":"   71","line":"    exit 1","class":"lineNoCov","hits":"0",},
{"lineNum":"   72","line":"  fi"},
{"lineNum":"   73","line":"}"},
{"lineNum":"   74","line":""},
{"lineNum":"   75","line":"#######################################"},
{"lineNum":"   76","line":"# Enable passwordless sudo for a user via a validated sudoers drop-in."},
{"lineNum":"   77","line":"# Globals:"},
{"lineNum":"   78","line":"#   DROPIN"},
{"lineNum":"   79","line":"# Arguments:"},
{"lineNum":"   80","line":"#   Target user (defaults to ${SUDO_USER})."},
{"lineNum":"   81","line":"#######################################"},
{"lineNum":"   82","line":"enable_nopasswd() {"},
{"lineNum":"   83","line":"  local user=\"${1:-${SUDO_USER:-}}\"","class":"lineCov","hits":"1","order":"2839",},
{"lineNum":"   84","line":"  if [[ -z \"${user}\" ]]; then","class":"lineCov","hits":"1","order":"2838",},
{"lineNum":"   85","line":"    log_error \"could not determine target user; pass one explicitly.\"","class":"lineCov","hits":"1","order":"2836",},
{"lineNum":"   86","line":"    exit 1","class":"lineCov","hits":"1","order":"2834",},
{"lineNum":"   87","line":"  fi"},
{"lineNum":"   88","line":"  if ! id -u \"${user}\" >/dev/null 2>&1; then","class":"lineCov","hits":"1","order":"2848",},
{"lineNum":"   89","line":"    log_error \"no such user: ${user}\"","class":"lineCov","hits":"1","order":"2849",},
{"lineNum":"   90","line":"    exit 1","class":"lineCov","hits":"1","order":"2857",},
{"lineNum":"   91","line":"  fi"},
{"lineNum":"   92","line":""},
{"lineNum":"   93","line":"  local tmp","class":"lineCov","hits":"1","order":"2832",},
{"lineNum":"   94","line":"  tmp=\"$(mktemp)\"","class":"lineCov","hits":"1","order":"2831",},
{"lineNum":"   95","line":"  printf \'%s ALL=(ALL) NOPASSWD:ALL\\n\' \"${user}\" >\"${tmp}\"","class":"lineCov","hits":"1","order":"2829",},
{"lineNum":"   96","line":""},
{"lineNum":"   97","line":"  # Validate BEFORE installing — a bad sudoers file can lock you out of sudo."},
{"lineNum":"   98","line":"  if ! visudo -cf \"${tmp}\" >/dev/null; then","class":"lineCov","hits":"1","order":"2851",},
{"lineNum":"   99","line":"    rm -f \"${tmp}\"","class":"lineCov","hits":"1","order":"2859",},
{"lineNum":"  100","line":"    log_error \"sudoers syntax check failed; not installing.\"","class":"lineCov","hits":"1","order":"2862",},
{"lineNum":"  101","line":"    exit 1","class":"lineCov","hits":"1","order":"2827",},
{"lineNum":"  102","line":"  fi"},
{"lineNum":"  103","line":""},
{"lineNum":"  104","line":"  install -m 0440 -o root -g root \"${tmp}\" \"${DROPIN}\"","class":"lineCov","hits":"1","order":"2826",},
{"lineNum":"  105","line":"  rm -f \"${tmp}\"","class":"lineCov","hits":"1","order":"2824",},
{"lineNum":"  106","line":"  log_info \"passwordless sudo ENABLED for \'${user}\' (${DROPIN}).\"","class":"lineCov","hits":"1","order":"2866",},
{"lineNum":"  107","line":"}"},
{"lineNum":"  108","line":""},
{"lineNum":"  109","line":"#######################################"},
{"lineNum":"  110","line":"# Arm a one-shot systemd timer that runs `off` after the timeout."},
{"lineNum":"  111","line":"# A transient timer is used so it survives this script (and the SSH session)"},
{"lineNum":"  112","line":"# exiting. Re-arming first cancels any existing timer, resetting the clock."},
{"lineNum":"  113","line":"# Globals:"},
{"lineNum":"  114","line":"#   AUTO_UNIT"},
{"lineNum":"  115","line":"# Arguments:"},
{"lineNum":"  116","line":"#   Timeout in minutes (0 disables auto-revoke)."},
{"lineNum":"  117","line":"#######################################"},
{"lineNum":"  118","line":"schedule_revoke() {"},
{"lineNum":"  119","line":"  local minutes=\"${1}\"","class":"lineCov","hits":"1","order":"2867",},
{"lineNum":"  120","line":"  cancel_revoke","class":"lineCov","hits":"1","order":"2868",},
{"lineNum":"  121","line":"  if [[ \"${minutes}\" -eq 0 ]]; then","class":"lineCov","hits":"1","order":"2869",},
{"lineNum":"  122","line":"    log_info \"auto-revoke DISABLED (timeout 0) — remember to run \'off\' yourself.\"","class":"lineCov","hits":"1","order":"2871",},
{"lineNum":"  123","line":"    return","class":"lineCov","hits":"1","order":"2874",},
{"lineNum":"  124","line":"  fi"},
{"lineNum":"  125","line":"  local self","class":"lineCov","hits":"1","order":"2876",},
{"lineNum":"  126","line":"  self=\"$(readlink -f \"$0\")\"","class":"lineCov","hits":"1","order":"2878",},
{"lineNum":"  127","line":"  local -a args=(--quiet --unit=\"${AUTO_UNIT}\" --on-active=\"${minutes}min\")","class":"lineCov","hits":"1","order":"2879",},
{"lineNum":"  128","line":"  args+=(--description=\"Auto-revoke temporary passwordless sudo\")","class":"lineCov","hits":"1","order":"2855",},
{"lineNum":"  129","line":"  args+=(\"${self}\" off)","class":"lineCov","hits":"1","order":"2860",},
{"lineNum":"  130","line":"  systemd-run \"${args[@]}\"","class":"lineCov","hits":"1","order":"2863",},
{"lineNum":"  131","line":"  log_info \"auto-revoke ARMED: passwordless sudo self-disables in ${minutes} min.\"","class":"lineCov","hits":"1","order":"2881",},
{"lineNum":"  132","line":"}"},
{"lineNum":"  133","line":""},
{"lineNum":"  134","line":"#######################################"},
{"lineNum":"  135","line":"# Cancel any pending auto-revoke timer (idempotent)."},
{"lineNum":"  136","line":"# Globals:"},
{"lineNum":"  137","line":"#   AUTO_UNIT"},
{"lineNum":"  138","line":"#######################################"},
{"lineNum":"  139","line":"cancel_revoke() {"},
{"lineNum":"  140","line":"  systemctl stop \"${AUTO_UNIT}.timer\" >/dev/null 2>&1 || true","class":"lineCov","hits":"1","order":"2843",},
{"lineNum":"  141","line":"  systemctl reset-failed \"${AUTO_UNIT}.service\" \"${AUTO_UNIT}.timer\" >/dev/null 2>&1 || true","class":"lineCov","hits":"1","order":"2846",},
{"lineNum":"  142","line":"}"},
{"lineNum":"  143","line":""},
{"lineNum":"  144","line":"#######################################"},
{"lineNum":"  145","line":"# Install and enable a persistent boot-time unit that revokes passwordless"},
{"lineNum":"  146","line":"# sudo on every boot. The in-session auto-revoke timer is transient and does"},
{"lineNum":"  147","line":"# NOT survive a reboot, so without this a reboot could strand the grant with"},
{"lineNum":"  148","line":"# nothing left to remove it. Idempotent; safe to leave enabled permanently"},
{"lineNum":"  149","line":"# (its `off` is a no-op when no drop-in is present)."},
{"lineNum":"  150","line":"# Globals:"},
{"lineNum":"  151","line":"#   BOOT_UNIT"},
{"lineNum":"  152","line":"#######################################"},
{"lineNum":"  153","line":"ensure_boot_revoke() {"},
{"lineNum":"  154","line":"  local self unit=\"${SYSTEMD_UNIT_DIR}/${BOOT_UNIT}.service\"","class":"lineCov","hits":"1","order":"2830",},
{"lineNum":"  155","line":"  self=\"$(readlink -f \"$0\")\"","class":"lineCov","hits":"1","order":"2882",},
{"lineNum":"  156","line":"  if [[ ! -f \"${unit}\" ]]; then","class":"lineCov","hits":"1","order":"2884",},
{"lineNum":"  157","line":"    cat >\"${unit}\" <<UNIT","class":"lineCov","hits":"1","order":"2853",},
{"lineNum":"  158","line":"[Unit]"},
{"lineNum":"  159","line":"Description=Revoke temporary passwordless sudo on boot"},
{"lineNum":"  160","line":"After=local-fs.target"},
{"lineNum":"  161","line":""},
{"lineNum":"  162","line":"[Service]"},
{"lineNum":"  163","line":"Type=oneshot"},
{"lineNum":"  164","line":"ExecStart=${self} off"},
{"lineNum":"  165","line":""},
{"lineNum":"  166","line":"[Install]"},
{"lineNum":"  167","line":"WantedBy=multi-user.target"},
{"lineNum":"  168","line":"UNIT"},
{"lineNum":"  169","line":"    systemctl daemon-reload","class":"lineCov","hits":"1","order":"2885",},
{"lineNum":"  170","line":"  fi"},
{"lineNum":"  171","line":"  systemctl enable \"${BOOT_UNIT}.service\" >/dev/null 2>&1 || true","class":"lineCov","hits":"1","order":"2886",},
{"lineNum":"  172","line":"}"},
{"lineNum":"  173","line":""},
{"lineNum":"  174","line":"#######################################"},
{"lineNum":"  175","line":"# Remove the passwordless sudo drop-in and cancel the auto-revoke timer."},
{"lineNum":"  176","line":"# Globals:"},
{"lineNum":"  177","line":"#   DROPIN"},
{"lineNum":"  178","line":"#######################################"},
{"lineNum":"  179","line":"disable_nopasswd() {"},
{"lineNum":"  180","line":"  if [[ -f \"${DROPIN}\" ]]; then","class":"lineCov","hits":"1","order":"2870",},
{"lineNum":"  181","line":"    rm -f \"${DROPIN}\"","class":"lineCov","hits":"1","order":"2872",},
{"lineNum":"  182","line":"    log_info \"passwordless sudo DISABLED (removed ${DROPIN}).\"","class":"lineCov","hits":"1","order":"2875",},
{"lineNum":"  183","line":"  else"},
{"lineNum":"  184","line":"    log_info \"already disabled (no ${DROPIN}).\"","class":"lineCov","hits":"1","order":"2877",},
{"lineNum":"  185","line":"  fi"},
{"lineNum":"  186","line":"  cancel_revoke","class":"lineCov","hits":"1","order":"2880",},
{"lineNum":"  187","line":"}"},
{"lineNum":"  188","line":""},
{"lineNum":"  189","line":"#######################################"},
{"lineNum":"  190","line":"# Report whether the drop-in is present and whether auto-revoke is armed."},
{"lineNum":"  191","line":"# Globals:"},
{"lineNum":"  192","line":"#   DROPIN"},
{"lineNum":"  193","line":"#   AUTO_UNIT"},
{"lineNum":"  194","line":"#   BOOT_UNIT"},
{"lineNum":"  195","line":"#######################################"},
{"lineNum":"  196","line":"show_status() {"},
{"lineNum":"  197","line":"  if [[ -f \"${DROPIN}\" ]]; then","class":"lineCov","hits":"1","order":"2887",},
{"lineNum":"  198","line":"    log_info \"ENABLED:\"","class":"lineCov","hits":"1","order":"2888",},
{"lineNum":"  199","line":"    sed \'s/^/  /\' \"${DROPIN}\"","class":"lineCov","hits":"1","order":"2844",},
{"lineNum":"  200","line":"  else"},
{"lineNum":"  201","line":"    log_info \"DISABLED (no ${DROPIN}).\"","class":"lineCov","hits":"1","order":"2841",},
{"lineNum":"  202","line":"  fi"},
{"lineNum":"  203","line":"  if systemctl is-active --quiet \"${AUTO_UNIT}.timer\" 2>/dev/null; then","class":"lineCov","hits":"1","order":"2823",},
{"lineNum":"  204","line":"    log_info \"auto-revoke (this session): ARMED\"","class":"lineCov","hits":"1","order":"2822",},
{"lineNum":"  205","line":"    local timers","class":"lineCov","hits":"1","order":"2821",},
{"lineNum":"  206","line":"    timers=$(systemctl list-timers \"${AUTO_UNIT}.timer\" --no-pager 2>/dev/null || true)","class":"lineCov","hits":"1","order":"2820",},
{"lineNum":"  207","line":"    sed -n \'2p\' <<<\"${timers}\" | sed \'s/^/  /\'","class":"lineCov","hits":"1","order":"2819",},
{"lineNum":"  208","line":"  else"},
{"lineNum":"  209","line":"    log_info \"auto-revoke (this session): not armed\"","class":"lineCov","hits":"1","order":"2818",},
{"lineNum":"  210","line":"  fi"},
{"lineNum":"  211","line":"  if systemctl is-enabled --quiet \"${BOOT_UNIT}.service\" 2>/dev/null; then","class":"lineCov","hits":"1","order":"2837",},
{"lineNum":"  212","line":"    log_info \"boot-revoke: enabled (passwordless sudo is cleared on every reboot)\"","class":"lineCov","hits":"1","order":"2835",},
{"lineNum":"  213","line":"  else"},
{"lineNum":"  214","line":"    log_info \"boot-revoke: NOT installed (a reboot would not clear a stale grant)\"","class":"lineCov","hits":"1","order":"2817",},
{"lineNum":"  215","line":"  fi"},
{"lineNum":"  216","line":"}"},
{"lineNum":"  217","line":""},
{"lineNum":"  218","line":"#######################################"},
{"lineNum":"  219","line":"# Entry point: dispatch on the requested action."},
{"lineNum":"  220","line":"#######################################"},
{"lineNum":"  221","line":"main() {"},
{"lineNum":"  222","line":"  case \"${1:-}\" in","class":"lineCov","hits":"1","order":"2828",},
{"lineNum":"  223","line":"    -h | --help | \"\") show_usage; exit 0 ;;","class":"lineCov","hits":"1","order":"2816",},
{"lineNum":"  224","line":"  esac"},
{"lineNum":"  225","line":"  require_root","class":"lineCov","hits":"1","order":"2850",},
{"lineNum":"  226","line":"  case \"${1}\" in","class":"lineCov","hits":"1","order":"2858",},
{"lineNum":"  227","line":"    on)"},
{"lineNum":"  228","line":"      # on [user] [minutes]; a bare numeric first arg is treated as minutes."},
{"lineNum":"  229","line":"      local user=\"\" minutes=\"${DEFAULT_TIMEOUT_MIN}\"","class":"lineCov","hits":"1","order":"2815",},
{"lineNum":"  230","line":"      if [[ \"${2:-}\" =~ ^[0-9]+$ ]]; then","class":"lineCov","hits":"1","order":"2814",},
{"lineNum":"  231","line":"        minutes=\"${2}\"","class":"lineCov","hits":"1","order":"2825",},
{"lineNum":"  232","line":"      else"},
{"lineNum":"  233","line":"        user=\"${2:-}\"","class":"lineCov","hits":"1","order":"2865",},
{"lineNum":"  234","line":"        [[ \"${3:-}\" =~ ^[0-9]+$ ]] && minutes=\"${3}\"","class":"lineCov","hits":"1","order":"2813",},
{"lineNum":"  235","line":"      fi"},
{"lineNum":"  236","line":"      # Install the boot-time safety net BEFORE granting, so a reboot can never"},
{"lineNum":"  237","line":"      # strand the grant even if everything after this point fails."},
{"lineNum":"  238","line":"      ensure_boot_revoke","class":"lineCov","hits":"1","order":"2812",},
{"lineNum":"  239","line":"      enable_nopasswd \"${user}\"","class":"lineCov","hits":"1","order":"2811",},
{"lineNum":"  240","line":"      schedule_revoke \"${minutes}\"","class":"lineCov","hits":"1","order":"2810",},
{"lineNum":"  241","line":"      ;;"},
{"lineNum":"  242","line":"    off)    disable_nopasswd ;;","class":"lineCov","hits":"1","order":"2809",},
{"lineNum":"  243","line":"    status) show_status ;;","class":"lineNoCov","hits":"0",},
{"lineNum":"  244","line":"    *)      log_error \"unknown command: ${1}\"; show_usage; exit 2 ;;","class":"lineCov","hits":"1","order":"2808",},
{"lineNum":"  245","line":"  esac"},
{"lineNum":"  246","line":"}"},
{"lineNum":"  247","line":""},
{"lineNum":"  248","line":"# Only run when executed, not when sourced — the test suite sources this file to exercise its"},
{"lineNum":"  249","line":"# individual functions."},
{"lineNum":"  250","line":"if [[ \"${BASH_SOURCE[0]}\" == \"${0}\" ]]; then","class":"lineCov","hits":"1","order":"2873",},
{"lineNum":"  251","line":"  main \"$@\"","class":"lineCov","hits":"1","order":"2807",},
{"lineNum":"  252","line":"fi"},
]};
